package gov.takx.commons.swing.actionlist;

import gov.tak.api.annotation.IncubatingApi;
import jakarta.annotation.Nonnull;
import jakarta.annotation.Nullable;

import javax.swing.AbstractButton;
import javax.swing.Action;

/**
 * Interface to allow customization of the buttons generated by the renderer.
 *
 * @param <T> the value type that this action expects (should match the value type in {@link ActionList})
 * @since 5.7
 */
@FunctionalInterface
@IncubatingApi(since = "5.7")
public interface ActionListButtonConfigurer<T>
{
    /**
     * Allows customization of buttons generated by the renderer.
     *
     * @param button the button component
     * @param action the action
     * @param value the action list value (See {@link ActionList#value()})
     * @param row the table row index
     */
    void configureButton(@Nonnull AbstractButton button, @Nonnull Action action, @Nullable T value, int row);
}
